#include <bits/stdc++.h>
using namespace std;

struct Rect {
    long long x1, y1, x2, y2;
};

long long pointDist(long long x, long long y, const Rect& r) {
    long long dx = 0, dy = 0;
    if (x < r.x1) dx = r.x1 - x;
    else if (x > r.x2) dx = x - r.x2;
    if (y < r.y1) dy = r.y1 - y;
    else if (y > r.y2) dy = y - r.y2;
    return dx + dy;
}

long long rectDist(const Rect& a, const Rect& b) {
    long long dx = 0, dy = 0;
    if (a.x2 < b.x1) dx = b.x1 - a.x2;
    else if (b.x2 < a.x1) dx = a.x1 - b.x2;
    if (a.y2 < b.y1) dy = b.y1 - a.y2;
    else if (b.y2 < a.y1) dy = a.y1 - b.y2;
    return dx + dy;
}

bool intersect(const Rect& a, const Rect& b) {
    return max(a.x1, b.x1) <= min(a.x2, b.x2) &&
           max(a.y1, b.y1) <= min(a.y2, b.y2);
}

struct DSU {
    vector<int> p, sz;
    DSU(int n = 0) {
        p.resize(n);
        sz.assign(n, 1);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        return p[x] == x ? x : p[x] = find(p[x]);
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long Xi, Yi, Xf, Yf;
    cin >> Xi >> Yi >> Xf >> Yf;
    int N;
    cin >> N;

    vector<Rect> rects(N);
    for (int i = 0; i < N; ++i) {
        cin >> rects[i].x1 >> rects[i].y1 >> rects[i].x2 >> rects[i].y2;
    }

    DSU dsu(N);
    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            if (intersect(rects[i], rects[j])) {
                dsu.unite(i, j);
            }
        }
    }

    vector<int> rootId(N, -1);
    int k = 0;
    vector<int> comp(N);
    for (int i = 0; i < N; ++i) {
        int r = dsu.find(i);
        if (rootId[r] == -1) rootId[r] = k++;
        comp[i] = rootId[r];
    }

    int M = k + 2;
    int S = k;
    int T = k + 1;
    const long long INF = 4e18;

    vector<vector<long long>> w(M, vector<long long>(M, INF));
    for (int i = 0; i < M; ++i) w[i][i] = 0;

    for (int i = 0; i < N; ++i) {
        int c = comp[i];
        long long ds = pointDist(Xi, Yi, rects[i]);
        long long dt = pointDist(Xf, Yf, rects[i]);
        if (ds < w[S][c]) {
            w[S][c] = w[c][S] = ds;
        }
        if (dt < w[T][c]) {
            w[T][c] = w[c][T] = dt;
        }
    }

    long long dx0 = Xi > Xf ? Xi - Xf : Xf - Xi;
    long long dy0 = Yi > Yf ? Yi - Yf : Yf - Yi;
    long long direct = dx0 + dy0;
    w[S][T] = min(w[S][T], direct);
    w[T][S] = w[S][T];

    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            int ci = comp[i];
            int cj = comp[j];
            if (ci == cj) continue;
            long long d = rectDist(rects[i], rects[j]);
            if (d < w[ci][cj]) {
                w[ci][cj] = w[cj][ci] = d;
            }
        }
    }

    vector<long long> dist(M, INF);
    vector<char> vis(M, 0);
    dist[S] = 0;

    for (int it = 0; it < M; ++it) {
        int u = -1;
        long long best = INF;
        for (int v = 0; v < M; ++v) {
            if (!vis[v] && dist[v] < best) {
                best = dist[v];
                u = v;
            }
        }
        if (u == -1) break;
        if (u == T) break;

        vis[u] = 1;
        for (int v = 0; v < M; ++v) {
            if (!vis[v] && w[u][v] < INF) {
                long long nd = dist[u] + w[u][v];
                if (nd < dist[v]) dist[v] = nd;
            }
        }
    }

    cout << dist[T] << '\n';
    return 0;
}
